factorial.code:
define function factorial (n :: <integer>) => (n! :: <integer>)
  if (n <= 1)
    1
  else
    n * factorial(n - 1)
  end if
end function factorial;

format-out("%d\n", factorial(10));

fizzbuzz.code:
for (i from 1 to 15)
  format-out("%s\n",
             case
               modulo(i, 15) = 0 => "FizzBuzz";
               modulo(i, 3) = 0  => "Fizz";
               modulo(i, 5) = 0  => "Buzz";
               otherwise         => integer-to-string(i);
             end case)
end for;

higher-order.code:
let numbers = range(from: 1, to: 10);
let squares = map(method (x) x * x end, choose(even?, numbers));

format-out("%s\n", join(map(integer-to-string, squares), " "));

shapes.code:
define abstract class <shape> (<object>) end class;

define class <rectangle> (<shape>)
  constant slot width :: <integer>, required-init-keyword: width:;
  constant slot height :: <integer>, required-init-keyword: height:;
end class;

define class <triangle> (<shape>)
  constant slot base :: <integer>, required-init-keyword: base:;
  constant slot height :: <integer>, required-init-keyword: height:;
end class;

// Generic functions hold the behaviour; each method specializes on a class.
define generic area (shape :: <shape>) => (area :: <integer>);
define method area (r :: <rectangle>) => (area :: <integer>) r.width * r.height end;
define method area (t :: <triangle>) => (area :: <integer>) floor/(t.base * t.height, 2) end;

define generic name (shape :: <shape>) => (name :: <string>);
define method name (r :: <rectangle>) => (name :: <string>) "Rectangle" end;
define method name (t :: <triangle>) => (name :: <string>) "Triangle" end;

for (shape in list(make(<rectangle>, width: 3, height: 4),
                   make(<triangle>, base: 10, height: 3)))
  format-out("%s: %d\n", shape.name, area(shape))
end for;

signature.code:
define abstract class <thing> (<object>)
  constant slot name :: <string>, required-init-keyword: name:;
end class;
define class <asteroid> (<thing>) end class;
define class <ship> (<thing>) end class;

// One generic function; Dylan picks the method from the classes of BOTH arguments.
define generic collide (a :: <thing>, b :: <thing>) => (outcome :: <string>);

define method collide (a :: <thing>, b :: <thing>) => (outcome :: <string>)
  "they bounce apart"
end method;
define method collide (a :: <asteroid>, b :: <ship>) => (outcome :: <string>)
  "the ship is destroyed"
end method;
define method collide (a :: <ship>, b :: <asteroid>) => (outcome :: <string>)
  collide(b, a)                               // same outcome, arguments swapped
end method;
define method collide (a :: <ship>, b :: <ship>) => (outcome :: <string>)
  concatenate(next-method(), ", then dock")   // extend the <thing>, <thing> method
end method;

let things = list(make(<asteroid>, name: "asteroid"), make(<ship>, name: "ship"));
for (a in things)
  for (b in things)
    format-out("%s hits %s: %s\n", a.name, b.name, collide(a, b))
  end for
end for;
